-- Apply BEFORE deploy. Preserve the historical migrations and existing grants.
-- This patches the embedded defaults only; guarded existing-row updates are
-- generated by scripts/americanize-starters.ts and reviewed before execution.
begin;
do $migration$
declare old_definition text; new_definition text;
begin
  select pg_catalog.pg_get_functiondef('public.seed_new_workspace_templates()'::regprocedure)
    into old_definition;
  new_definition := replace(replace(old_definition,
    'can be cancelled with 30 days'' notice', 'can be canceled with 30 days'' notice'),
    'Your logo, brand colours and any photos', 'Your logo, brand colors and any photos');
  if new_definition <> old_definition then execute new_definition; end if;
end $migration$;
commit;
